package pl.zagranietyper.repository;import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.model.FootballFixturePlayerStatisticsSnapshot;import java.sql.*;import java.util.*;
public final class FootballFixturePlayerStatisticsRepository {private final Database db;private final ObjectMapper mapper;public FootballFixturePlayerStatisticsRepository(Database d,ObjectMapper m){db=d;mapper=m;}public boolean store(FootballFixturePlayerStatisticsSnapshot s){try(Connection c=db.openConnection()){c.setAutoCommit(false);try{var old=lock(c,s.fixtureId());if(!shouldReplace(old.orElse(null),s.status())){c.rollback();return false;}upsertFetch(c,s);if(s.status()==FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE){try(var p=c.prepareStatement("DELETE FROM api_football_fixture_player_statistics WHERE fixture_id=?")){p.setLong(1,s.fixtureId());p.executeUpdate();}insert(c,s);}c.commit();return true;}catch(Exception e){c.rollback();throw e;}}catch(Exception e){throw new IllegalStateException("Could not store fixture player statistics",e);}}public Optional<FootballFixturePlayerStatisticsSnapshot.FetchStatus>loadStatus(long id){try(Connection c=db.openConnection();var p=c.prepareStatement("SELECT status FROM api_football_fixture_player_stat_fetches WHERE fixture_id=?")){p.setLong(1,id);try(var r=p.executeQuery()){return r.next()?Optional.of(FootballFixturePlayerStatisticsSnapshot.FetchStatus.valueOf(r.getString(1))):Optional.empty();}}catch(SQLException e){throw new IllegalStateException(e);}}public List<FootballFixturePlayerStatisticsSnapshot.Player>loadPlayers(long id){String q="SELECT team_id,team_name,player_id,player_name,minutes,position,rating,captain,substitute,offsides,shots_total,shots_on_target,goals,assists,saves,passes_total,passes_key,passes_accuracy,tackles,blocks,interceptions,duels_total,duels_won,dribbles_attempts,dribbles_success,dribbles_past,fouls_drawn,fouls_committed,yellow_cards,red_cards,penalties,raw_statistics FROM api_football_fixture_player_statistics WHERE fixture_id=? ORDER BY team_id,player_id";try(Connection c=db.openConnection();var p=c.prepareStatement(q)){p.setLong(1,id);try(var r=p.executeQuery()){List<FootballFixturePlayerStatisticsSnapshot.Player>o=new ArrayList<>();while(r.next())o.add(new FootballFixturePlayerStatisticsSnapshot.Player(nl(r,1),r.getString(2),nl(r,3),r.getString(4),ni(r,5),r.getString(6),r.getString(7),nb(r,8),nb(r,9),ni(r,10),ni(r,11),ni(r,12),ni(r,13),ni(r,14),ni(r,15),ni(r,16),ni(r,17),r.getString(18),ni(r,19),ni(r,20),ni(r,21),ni(r,22),ni(r,23),ni(r,24),ni(r,25),ni(r,26),ni(r,27),ni(r,28),ni(r,29),ni(r,30),json(r.getString(31)),json(r.getString(32))));return List.copyOf(o);}}catch(Exception e){throw new IllegalStateException(e);}}public static boolean shouldReplace(FootballFixturePlayerStatisticsSnapshot.FetchStatus old,FootballFixturePlayerStatisticsSnapshot.FetchStatus incoming){return old!=FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE||incoming==FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE;}private Optional<FootballFixturePlayerStatisticsSnapshot.FetchStatus>lock(Connection c,long id)throws SQLException{try(var p=c.prepareStatement("SELECT status FROM api_football_fixture_player_stat_fetches WHERE fixture_id=? FOR UPDATE")){p.setLong(1,id);try(var r=p.executeQuery()){return r.next()?Optional.of(FootballFixturePlayerStatisticsSnapshot.FetchStatus.valueOf(r.getString(1))):Optional.empty();}}}private void upsertFetch(Connection c,FootballFixturePlayerStatisticsSnapshot s)throws Exception{String q="INSERT INTO api_football_fixture_player_stat_fetches(fixture_id,status,source,http_status,returned_player_count,error_message,raw_json,fetched_at,parser_version)VALUES(?,?,?,?,?,?,?::jsonb,?,?) ON CONFLICT(fixture_id)DO UPDATE SET status=EXCLUDED.status,source=EXCLUDED.source,http_status=EXCLUDED.http_status,returned_player_count=EXCLUDED.returned_player_count,error_message=EXCLUDED.error_message,raw_json=EXCLUDED.raw_json,fetched_at=EXCLUDED.fetched_at,parser_version=EXCLUDED.parser_version,updated_at=NOW() WHERE api_football_fixture_player_stat_fetches.status<>'COMPLETE' OR EXCLUDED.status='COMPLETE'";try(var p=c.prepareStatement(q)){p.setLong(1,s.fixtureId());p.setString(2,s.status().name());p.setString(3,s.source());if(s.httpStatus()==null)p.setNull(4,Types.INTEGER);else p.setInt(4,s.httpStatus());p.setInt(5,s.players().size());p.setString(6,s.errorMessage());p.setString(7,s.rawJson());p.setTimestamp(8,Timestamp.from(s.fetchedAt()));p.setInt(9,s.parserVersion());p.executeUpdate();}}private void insert(Connection c,FootballFixturePlayerStatisticsSnapshot s)throws Exception{String q="INSERT INTO api_football_fixture_player_statistics VALUES("+String.join(",",Collections.nCopies(36,"?"))+")";try(var p=c.prepareStatement(q)){for(var x:s.players()){int i=1;p.setLong(i++,s.fixtureId());sl(p,i++,x.teamId());p.setString(i++,x.teamName());sl(p,i++,x.playerId());p.setString(i++,x.playerName());si(p,i++,x.minutes());p.setString(i++,x.position());p.setString(i++,x.rating());sb(p,i++,x.captain());sb(p,i++,x.substitute());si(p,i++,x.offsides());si(p,i++,x.shotsTotal());si(p,i++,x.shotsOnTarget());si(p,i++,x.goals());si(p,i++,x.assists());si(p,i++,x.saves());si(p,i++,x.passesTotal());si(p,i++,x.passesKey());p.setString(i++,x.passesAccuracy());si(p,i++,x.tackles());si(p,i++,x.blocks());si(p,i++,x.interceptions());si(p,i++,x.duelsTotal());si(p,i++,x.duelsWon());si(p,i++,x.dribblesAttempts());si(p,i++,x.dribblesSuccess());si(p,i++,x.dribblesPast());si(p,i++,x.foulsDrawn());si(p,i++,x.foulsCommitted());si(p,i++,x.yellowCards());si(p,i++,x.redCards());p.setObject(i++,x.penalties()==null?null:mapper.writeValueAsString(x.penalties()),Types.OTHER);p.setObject(i++,mapper.writeValueAsString(x.rawStatistics()),Types.OTHER);p.setString(i++,s.source());p.setTimestamp(i++,Timestamp.from(s.fetchedAt()));p.setInt(i,s.parserVersion());p.addBatch();}p.executeBatch();}}private com.fasterxml.jackson.databind.JsonNode json(String s)throws Exception{return s==null?null:mapper.readTree(s);}private static void sl(PreparedStatement p,int i,Long v)throws SQLException{if(v==null)p.setNull(i,Types.BIGINT);else p.setLong(i,v);}private static void si(PreparedStatement p,int i,Integer v)throws SQLException{if(v==null)p.setNull(i,Types.INTEGER);else p.setInt(i,v);}private static void sb(PreparedStatement p,int i,Boolean v)throws SQLException{if(v==null)p.setNull(i,Types.BOOLEAN);else p.setBoolean(i,v);}private static Long nl(ResultSet r,int i)throws SQLException{long v=r.getLong(i);return r.wasNull()?null:v;}private static Integer ni(ResultSet r,int i)throws SQLException{int v=r.getInt(i);return r.wasNull()?null:v;}private static Boolean nb(ResultSet r,int i)throws SQLException{boolean v=r.getBoolean(i);return r.wasNull()?null:v;}}
